>LS</text><line x1="76" y1="128" x2="76" y2="158" stroke="#888" stroke-width="1.6"/><line x1="58" y1="158" x2="188" y2="158" stroke="#888" stroke-width="1.6"/><text x="192" y="162" fill="#888" font-size="11">GND</text><path d="M336,158 V92 H430 V158 H336" fill="none" stroke="#eab308" stroke-width="7" stroke-opacity="0.35" stroke-linecap="round" stroke-linejoin="round"/><text x="358" y="34" fill="#00d4ff" font-size="11" font-weight="bold" text-anchor="middle">Phase 2: HS OFF, LS ON</text><text x="272" y="44" fill="#ff6b6b" font-size="11">VIN</text><line x1="302" y1="50" x2="318" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="318" y="38" width="36" height="24" rx="3" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="336" y="54" fill="#00ff88" font-size="11" text-anchor="middle">HS</text><line x1="336" y1="62" x2="336" y2="104" stroke="#ffc107" stroke-width="2"/><text x="310" y="88" fill="#ffc107" font-size="11" text-anchor="end">SW</text><line x1="336" y1="92" x2="352" y2="92" stroke="#ffc107" stroke-width="2"/><rect x="352" y="82" width="46" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="375" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">L</text><line x1="398" y1="92" x2="430" y2="92" stroke="#888" stroke-width="1.6"/><circle cx="430" cy="92" r="3" fill="#888"/><line x1="430" y1="92" x2="430" y2="112" stroke="#888" stroke-width="1.6"/><rect x="412" y="112" width="36" height="28" rx="3" fill="none" stroke="#888" stroke-width="1.6"/><text x="430" y="131" fill="#888" font-size="11" text-anchor="middle">Load</text><line x1="430" y1="140" x2="430" y2="158" stroke="#888" stroke-width="1.6"/><rect x="318" y="104" width="36" height="24" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="336" y="120" fill="#00d4ff" font-size="11" text-anchor="middle">LS</text><line x1="336" y1="128" x2="336" y2="158" stroke="#888" stroke-width="1.6"/><line x1="318" y1="158" x2="448" y2="158" stroke="#888" stroke-width="1.6"/><text x="452" y="162" fill="#888" font-size="11">GND</text><line x1="260" y1="30" x2="260" y2="180" stroke="#334155" stroke-width="1"/><text x="10" y="214" fill="#888" font-size="11">Phase 1: iL rises, di/dt = (VIN - VOUT)/L    Phase 2: iL falls, di/dt = -VOUT/L</text></svg></div>$vsq$)
 where question like $q$%Buck 轉換器的電流路徑圖%$q$;

-- 驗收：三列都要 zh_has_svg = t 且 en_has_svg = t，empty_box_left = f
select id, left(question, 24) as q,
       answer    like '%<svg%' as zh_has_svg,
       answer_en like '%<svg%' as en_has_svg,
       (answer like $box$%<div class="exam-diagram-box"></div>%$box$ or answer_en like $box$%<div class="exam-diagram-box"></div>%$box$) as empty_box_left
  from public.interview_questions
 where question like $q$%Open-Drain 與 Push-Pull%$q$
    or question like $q$%I2C Bus 介面配線圖%$q$
    or question like $q$%Buck 轉換器的電流路徑圖%$q$;
